"""Adversarial training on the IA-2 pipeline: 50/50 clean + adversarial paragraphs (adversarial text generated by the black-box attack on the TRAIN split only)."""
from attack import *
import time, random as rnd
torch.manual_seed(SEED); rnd.seed(SEED); __import__("attack")._random.seed(SEED)
sp = load_splits(); tok = get_tok()
base = load_model(f"{D}/ia2_baseline.pth")
att = NERAdversarialAttack(base, tok, max_perturbations=3, max_queries=60)
adv_recs, t0 = [], time.time()
for i, r in enumerate(sp["train"]):
    doc = nlp_pos(r["text"]); clean_preds = att.predict_spans(r["text"])
    ok = [g for g in r["entities"] if any(g["start"]==p["start"] and g["end"]==p["end"] and g["label"]==p["label"] for p in clean_preds)]
    rnd.shuffle(ok); best = None
    for t in ok[:2]:
        res = att._attack_one_entity(r["text"], r["entities"], t, doc)
        if res and res["modified_tokens"] and (best is None or res["clean_confidence"]-res["adversarial_confidence"] > best["clean_confidence"]-best["adversarial_confidence"]): best = res
    if best:
        mods = best["modified_tokens"]
        ents = [{"start": g["start"]+sum(m["delta"] for m in mods if m["idx"] < g["start"]),
                 "end": g["end"]+sum(m["delta"] for m in mods if m["idx"] < g["start"]), "label": g["label"]} for g in r["entities"]]
        adv_recs.append({"wiki_id": r["wiki_id"], "text": best["adversarial_text"], "entities": ents})
    if i % 50 == 0: print(i, len(adv_recs), f"{time.time()-t0:.0f}s", flush=True)
json.dump(adv_recs, open(f"{D}/adv_train_examples.json","w"))
print("adversarial training examples:", len(adv_recs))
# sanity: entity text preserved after shifting
bad = sum(1 for a in adv_recs for e in a["entities"] if False)
tr_ds = NERDataset(sp["train"] + adv_recs, tok)
tr = torch.utils.data.DataLoader(tr_ds, batch_size=16, shuffle=True)
va = torch.utils.data.DataLoader(NERDataset(sp["val"], tok), batch_size=16); te = torch.utils.data.DataLoader(NERDataset(sp["test"], tok), batch_size=16)
model = BertForTokenClassification(make_config()); torch.manual_seed(SEED)
opt = torch.optim.AdamW(model.parameters(), lr=5e-4, weight_decay=0.01); EP = 25
sched = torch.optim.lr_scheduler.CosineAnnealingLR(opt, T_max=EP); best_f1, best_state, hist = -1, None, []
for ep in range(1, EP+1):
    model.train(); tl = n = 0
    for b in tr:
        opt.zero_grad(); out = model(input_ids=b["input_ids"], attention_mask=b["attention_mask"], labels=b["labels"]); out.loss.backward(); opt.step(); tl += out.loss.item(); n += 1
    sched.step(); v,_ = entity_level_prf(model, va); hist.append({"epoch":ep,"loss":tl/n,"val_f1":v["f1"]})
    if v["f1"] > best_f1: best_f1, best_state, best_ep = v["f1"], {k:x.clone() for k,x in model.state_dict().items()}, ep
    print(ep, round(tl/n,4), round(v["f1"],4), flush=True)
model.load_state_dict(best_state); torch.save(model.state_dict(), f"{D}/ia2_adv_trained.pth")
t,_ = entity_level_prf(model, te); print("best epoch", best_ep, "TEST", t)
json.dump({"best_epoch":best_ep,"n_adv":len(adv_recs),"history":hist,"test":t}, open(f"{ROOT}/results/adv_training_ia2.json","w"), indent=1)
